sp_widget.css:
.sp-card-grid {
    display: flex;
    flex-wrap: wrap;
}
.sp-card-grid > [class*="col-"] {
    display: flex;
    margin-bottom: 24px;
}
.sp-stat-panel {
    width: 100%;
    border-top: 3px solid $border-tertiary;
    border-radius: $border-radius-large;
    box-shadow: 0 1px 4px rgba($text-color, 0.07);
    margin-bottom: 0;
}
.sp-stat-info {
    border-top-color: $brand-info;
}
.sp-stat-warning {
    border-top-color: $brand-warning;
}
.sp-stat-success {
    border-top-color: $brand-success;
}
.sp-stat-danger {
    border-top-color: $brand-danger;
}
.sp-stat-value {
    font-size: 32px;
    font-weight: 700;
    color: $text-color;
    line-height: 1;
    margin-bottom: 8px;
}
.sp-stat-label {
    font-size: $font-size-small;
    color: $text-muted;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    font-weight: 600;
}
.sp-stat-icon {
    font-size: 20px;
    color: $text-muted;
    opacity: 0.5;
    margin-top: 12px;
    display: block;
}

sp_widget.script:
(function() {
    var table = 'x_839216_public_0_health_service_request_v1';
    data.totalRequests = 0;
    data.inProgress = 0;
    data.approved = 0;
    data.rejected = 0;

    var gr = new GlideRecord(table);
    gr.addQuery('active', true);
    gr.setLimit(1000);
    gr.query();
    while (gr.next()) {
        data.totalRequests++;
        var status = gr.getValue('u_status');
        if (status === 'in_progress') {
            data.inProgress++;
        } else if (status === 'approved') {
            data.approved++;
        } else if (status === 'rejected') {
            data.rejected++;
        }
    }
})();
